  "description": "Ticket search, closure and raw SQL access for Acme support agents",
  "version": "1.4.0",
  "repository": { "url": "https://github.com/acme-example/acme-support-agents", "source": "github" },
  "packages": [
    {
      "registryType": "pypi",
      "identifier": "acme-tickets-mcp",
      "version": "1.4.0",
      "transport": { "type": "stdio" },
