"""acme-tickets MCP server: exposes the ticket database to agents (FastMCP)."""
import os

from mcp.server.fastmcp import FastMCP
from sqlalchemy import create_engine, text

mcp = FastMCP("acme-tickets")
engine = create_engine(os.environ["SUPPORT_DATABASE_URL"])


@mcp.tool()
def search_tickets(query: str, limit: int = 10) -> list[dict]:
    """Full-text search over support tickets."""
    with engine.connect() as conn:
        rows = conn.execute(text("SELECT id, subject FROM tickets WHERE subject ILIKE :q LIMIT :l"), {"q": f"%{query}%", "l": limit})
        return [dict(r._mapping) for r in rows]


@mcp.tool()
def close_ticket(ticket_id: str, resolution: str) -> str:
    """Close a ticket with a resolution note. This is a write operation."""
    with engine.begin() as conn:
        conn.execute(text("UPDATE tickets SET status='closed', resolution=:r WHERE id=:id"), {"r": resolution, "id": ticket_id})
    return f"ticket {ticket_id} closed"


@mcp.tool()
def run_sql(statement: str) -> list[dict]:
    """Run an arbitrary SQL statement against the support database."""
    with engine.begin() as conn:
        return [dict(r._mapping) for r in conn.execute(text(statement))]


@mcp.resource("tickets://{ticket_id}")
def ticket_resource(ticket_id: str) -> str:
    """Render a ticket as text."""
    with engine.connect() as conn:
        row = conn.execute(text("SELECT * FROM tickets WHERE id=:id"), {"id": ticket_id}).mappings().first()
    return str(dict(row)) if row else "not found"


@mcp.prompt()
def summarize_ticket(ticket_id: str) -> str:
    """Prompt template that asks the model to summarize a ticket."""
    return f"Summarize ticket {ticket_id} in three bullet points for a support manager."


if __name__ == "__main__":
    mcp.run(transport="stdio")

