// notify-mcp: an MCP server that lets agents email customers.
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import nodemailer from "nodemailer";
import { z } from "zod";

const transporter = nodemailer.createTransport({
  host: "smtp.acme.example",
  port: 587,
  auth: { user: "support-bot", pass: process.env.SMTP_PASSWORD },
});

const server = new McpServer({ name: "notify-mcp", version: "0.3.1" });

server.tool(
  "send_email",
  "Send an email to a customer on behalf of Acme Support",
  { to: z.string().email(), subject: z.string(), body: z.string() },
  async ({ to, subject, body }) => {
    const info = await transporter.sendMail({ from: "support@acme.example", to, subject, text: body });
    return { content: [{ type: "text", text: `sent ${info.messageId}` }] };
  },
);

const transport = new StdioServerTransport();
await server.connect(transport);

// Coding assistant used by the internal developer portal. Built on the Vercel AI SDK.
import { anthropic } from "@ai-sdk/anthropic";
import { generateText, tool } from "ai";
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { z } from "zod";

const SYSTEM = `You are Acme's coding assistant. You may run shell commands and edit files in the
checked-out repository to fix CI failures. Never touch production credentials.`;

export async function assist(task: string) {
  return generateText({
    model: anthropic("claude-opus-4-1"),
    system: SYSTEM,
    prompt: task,
    tools: {
      run_shell: tool({
        description: "Run a shell command in the repository checkout and return stdout",
        inputSchema: z.object({ command: z.string() }),
        execute: async ({ command }) => execSync(command, { encoding: "utf8", timeout: 60_000 }),
      }),
      write_file: tool({
        description: "Overwrite a file in the repository with new contents",
        inputSchema: z.object({ path: z.string(), contents: z.string() }),
        execute: async ({ path, contents }) => {
          writeFileSync(path, contents);
          return `wrote ${path}`;
        },
      }),
    },
    maxSteps: 12,
  });
}

